/** 
 * Sets the LDAP field name that the user's name is stored in. By default this is "cn". Another common value is "displayName".
 * @param nameField the LDAP field that that corresponds to the user's name.
 */
public void setNameField(String nameField){
  this.nameField=nameField;
  try {
    if (nameField == null) {
      properties.remove("ldap.nameField");
    } else {
      properties.put("ldap.nameField",nameField);
    }
  } catch (UnsupportedOperationException | IllegalArgumentException e) {
    // Handle or log the exception as needed
    e.printStackTrace();
  }
}
